import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { deleteStudent } from '../redux/studentSlice';



function StudentList() {
  const students = useSelector(state => state.students);
  const dispatch = useDispatch();

  return (
    <div>
      <h3>Students List</h3>
      <table border="1">
        <thead>
          <tr>
            <th>Name</th><th>Email</th><th>Gender</th><th>Age</th><th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {students.map((s, i) => (
            <tr key={i}>
              <td>{s.name}</td>
              <td>{s.email}</td>
              <td>{s.gender}</td>
              <td>{s.age}</td>
              <td>
                <button onClick={() => dispatch(deleteStudent(i))}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default StudentList;
